command:
const r = await tools.exec_command({"cmd":"$base = '<PROJECT>\script_vs_context_benchmark\source_artifacts\e2-n1000-v1'
$pages = @('page-001.jsonl','page-002.jsonl','page-003.jsonl','page-004.jsonl','page-005.jsonl','page-006.jsonl','page-007.jsonl','page-008.jsonl','page-009.jsonl','page-010.jsonl','page-011.jsonl','page-012.jsonl','page-013.jsonl','page-014.jsonl','page-015.jsonl','page-016.jsonl','page-017.jsonl','page-018.jsonl','page-019.jsonl','page-020.jsonl')
function Parse-Damage($v) { $s = [string]$v; if ($s -match '^(?:\d+|[1-9]\d{0,2}(?:,\d{3})+)$') { return [Int64]($s -replace ',','') }; return $null }
function Parse-Count($v) { $s = [string]$v; if ($s -match '^\d+$') { return [Int64]$s }; return $null }
'raw_id,report_year,track_type,severity_class,valid_damage_usd,valid_injured,valid_hazmat'
foreach ($page in $pages) {
  Get-Content -LiteralPath (Join-Path $base $page) | ForEach-Object {
    $r = $_ | ConvertFrom-Json
    $d = Parse-Damage $r.damage_text
    $i = Parse-Count $r.injured_text
    $h = Parse-Count $r.hazmat_released_text
    if ($null -eq $d -or $null -eq $i -or $null -eq $h) { $severity = 'unknown' }
    elseif ($i -gt 0 -or $h -gt 0 -or $d -ge 1000000) { $severity = 'critical' }
    elseif ($d -ge 100000) { $severity = 'high' }
    elseif ($d -ge 10000) { $severity = 'medium' }
    else { $severity = 'low' }
    '{0},{1},{2},{3},{4},{5},{6}' -f $r.raw_id,$r.report_year,$r.track_type,$severity,$d,$i,$h
  }
}","workdir":"<PROJECT>","yield_time_ms":30000,"max_output_tokens":60000});
text(r.output);
